NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Nahum'

CHAPTERS = {
    1: {
        1: 'Breme Niniv. Knjiga videnja Nahuma Elkošána.',
        2: 'Bog je ljubosumen in Gospod maščuje; Gospod maščuje in je razjarjen; Gospod se bo maščeval na svojih nasprotnikih in on prihranja bes za svoje sovražnike.',
        3: 'Gospod je počasen za jezo in silen v moči in sploh ne bo oprostil tožbe zlobnih. Gospod ima svojo pot v vrtinčastem vetru in v viharju in oblaki so prah njegovih stopal.',
        4: 'Ošteva morje in ga osušuje in suši vse reke. Bašán peša in Karmel in cvet Libanona peša.',
        5: 'Gore se tresejo ob njem in hribi se topijo in zemlja je sežgana ob njegovi prisotnosti, da, zemeljski [krog] in vsi, ki prebivajo na njem.',
        6: 'Kdo lahko obstane pred njegovim ogorčenjem? In kdo lahko prebiva v okrutnosti njegove jeze? Njegova razjarjenost je izlita kakor ogenj in skale so vržene dol po njem.',
        7: 'Gospod je dober, oporišče v dnevu stiske in pozna tiste, ki zaupajo vanj.',
        8: 'Toda s preplavljajočo povodnjijo bo naredil popoln konec njihovemu kraju in tema bo zasledovala njegove sovražnike.',
        9: 'Kaj si domišljate zoper Gospoda? On bo naredil popoln konec. Stiska se drugič ne bo vzdignila.',
        10: 'Kajti medtem ko so zviti skupaj kakor trnje in medtem ko so pijani kakor pijanci, bodo požrti kakor popolnoma suho strnišče.',
        11: 'Nekdo je izšel iz tebe, ki si je zoper Gospoda domišljal hudobijo, zloben svetovalec.',
        12: 'Tako govori Gospod: »Čeprav so tihi in prav tako številni, vendar bodo tako posekani, ko bo šel skozi. Čeprav sem te prizadel, te ne bom več prizadel.«',
        13: 'Kajti sedaj bom zlomil njegov jarem iznad tebe in tvoje vezi razpočil narazen.',
        14: 'Gospod je glede tebe dal zapoved, da se ne bo več sejalo iz tvojega imena. Iz hiše tvojih bogov bom iztrebil izrezljano podobo in ulito podobo. Pripravil ti bom grob; kajti hudoben si.',
        15: 'Poglej na gorah stopala tistega, ki prinaša dobre novice, ki razglaša mir! Oh Juda, ohranjaj svoje slovesne praznike, izpolni svoje zaobljube, kajti zlobni ne bo šel več skozte; popolnoma je uničen.',
    },
    2: {
        1: 'Kdor razbija na koščke je prišel gor, pred tvoj obraz. Varuj oporišče, pazi na pot, naredi svoja ledja močna, mogočno utrdi svojo moč.',
        2: 'Kajti Gospod je odvrnil Jakobovo odličnost kakor odličnost Izraela, kajti izpraznjevalci so jih izpraznili in skazili njihove trtne mladike.',
        3: 'Ščit njegovih mogočnih mož je pordečel, hrabri možje so v škrlatu. Bojni vozovi bodo s plamenečimi baklami na dan njegove priprave in ciprese bodo strašno stresene.',
        4: 'Bojni vozovi bodo besneli po ulicah, zadevali se bodo drug ob drugega na širokih poteh, zdeli se bodo kakor bakle, tekli bodo kakor bliski.',
        5: 'Spomnil se bo svojih vrlih. Spotaknili se bodo v svoji hoji, podvizali se bodo k njegovemu obzidju in obramba bo pripravljena.',
        6: 'Velika vrata rek bodo odprta in palača se bo raztopila.',
        7: '§ Huzzab bo odvedena v ujetništvo, privedena bo gor in njene služabnice jo bodo vodile kakor z glasom golobic, ki se bijejo po svojih prsih.',
        8: 'Toda Ninive so od davnine podobne vodnemu zbiralniku, vendar bodo pobegnile. »Stojte, stojte;« bodo kričali toda, nihče ne bo pogledal nazaj.',
        9: 'Vzemite plen srebra, vzemite plen zlata, kajti ni konca zaloge in slave vseh dragocenih stvari.',
        10: 'Prazna je, izpraznjena in opustošena. Srce se topi in kolena udarjajo skupaj in precej bolečine je v vseh ledjih in vsi njihovi obrazi zbirajo črnino.',
        11: 'Kje je prebivališče levov in kraj za hranjenje mladih levov, kjer je hodil lev, celó star lev in levji mladič in nihče ju ni prestrašil?',
        12: 'Lev je raztrgal na koščke dovolj za svoje mladiče in zadavil za svoje levinje in svoje jame napolnil s plenom in svoje brloge z ropom.',
        13: '»Glej, jaz sem zoper tebe,« govori Gospod nad bojevniki, »in jaz bom sežgal njene bojne vozove v dimu in meč bo použil tvoje mlade leve in iztrebil bom tvoj plen z zemlje in glasu tvojih poslancev ne bo več slišati.«',
    },
    3: {
        1: 'Gorje krvoločnemu mestu! To je polno laži in ropa, plen ga ne zapusti.',
        2: 'Tlesk biča in hrup ropotanja koles in drvečih konj in poskakujočih bojnih vozov.',
        3: 'Konjenik dviguje tako bleščeč meč kakor lesketajočo sulico in tam je množica umorjenih in veliko število trupel in tam ni konca njihovih trupel; spotikajo se na njihovih truplih.',
        4: 'Zaradi številnih vlačugarstev dobro favorizirane pocestnice, gospodarice čaranj, ki prodaja narode preko svojih vlačugarstev in družine preko svojih čaranj.',
        5: '»Glej, jaz sem zoper tebe,« govori Gospod nad bojevniki, »in odkril bom krajce tvojega oblačila nad tvojim obrazom in narodom bom pokazal tvojo nagoto in kraljestvom tvojo sramoto.',
        6: 'Nate bom vrgel gnusno umazanijo in te naredil ogabno in te postavil kakor predmet zaničevanja.',
        7: 'In zgodilo se bo, da bodo vsi, ki gledajo nate, pobegnili od tebe in rekli: ›Ninive so opustošene, kdo jih bo objokoval? Od kod bom iskal tolažnike zate?‹',
        8: 'Mar si boljša kakor gosto naseljen No, ki je bil umeščen med reke, ki je imel okoli sebe vode, katerega obrambni zid je bilo morje in je bil njegov zid od morja?',
        9: 'Etiopija in Egipt sta bila njegova moč in ta je bila neskončna; Put in Libija sta bila tvoja pomočnika.',
        10: 'Vendar je bil odveden proč, odšel je v ujetništvo. Tudi njegovi mladi otroci so bili raztreščeni na koščke na vrhu vseh ulic in metali so žrebe za njegove častitljive može in vsi njegovi veliki možje so bili zvezani v verigah.',
        11: 'Tudi ti boš pijana. Skrita boš, tudi ti boš iskala moč zaradi sovražnika.',
        12: 'Vsa tvoja oporišča bodo podobna figovemu drevesu s sadom prvih fig. Če bodo potresena, bodo torej padla v usta jedca.',
        13: 'Glej, tvoje ljudstvo v tvoji sredi so ženske. Velika vrata tvoje dežele bodo na široko odprta tvojim sovražnikom. Ogenj bo pogoltnil tvoje zapahe.',
        14: 'Zajemi vode zaradi obleganja, utrdi svoja oporišča. Pojdi v ilo in tlači malto, ojačaj opekarsko peč.',
        15: 'Tam te bo požrl ogenj, odsekal te bo meč, pojedel te bo kakor škodljiva gosenica. Naredi se tako številna kakor škodljiva gosenica, naredi se tako številna kakor leteče kobilice.',
        16: 'Pomnožila si svoje trgovce nad [številom] zvezd neba. Škodljiva gosenica uničuje in odleti proč.',
        17: 'Tvoji kronani so kakor leteče kobilice in tvoji poveljniki kakor velike kobilice, ki taborijo na ograjah na mrzel dan, toda ko vstane sonce, odletijo proč in nihče ne ve za prostor, kjer so.',
        18: 'Tvoji pastirji dremajo, oh asirski kralj, tvoji plemiči bodo prebivali v prahu, tvoje ljudstvo je razkropljeno po gorah in nihče jih ne zbira.',
        19: 'Ni ozdravljenja tvojega zloma, tvoja rana je boleča. Vsi, ki slišijo objavo o tebi, bodo z rokami ploskali nad teboj, kajti nad kom tvoja zlobnost ni nenehno besnela?«',
    },
}
